@namespace sv_ec1c5742dd1a421598cb83901c6d739e.Components.Pages.Apply
@using sv_ec1c5742dd1a421598cb83901c6d739e.Models

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="Model.FullName" placeholder="Enter your full name" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Model.Email" placeholder="Enter your email" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Model.Phone" placeholder="Enter your phone number" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Model.Address" placeholder="Enter your address" />
    </div>

    <div class="step-buttons">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        var emailValid = await ValidateEmail(Model.Email);
        IsValidating = false;

        if (!emailValid)
        {
            ErrorMessage = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

