@namespace sv_ec1c5742dd1a421598cb83901c6d739e.Components.Pages.Apply
@using sv_ec1c5742dd1a421598cb83901c6d739e.Models

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    @if (ShowRemove)
    {
        <button class="btn-danger-sm" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" @bind="Reference.Name" placeholder="Reference name" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" @bind="Reference.Relationship" placeholder="e.g., Former Manager" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" @bind="Reference.Email" placeholder="Email" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" @bind="Reference.Phone" placeholder="Phone" />
        </div>
    </div>
</div>

@code {
    [Parameter] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_ec1c5742dd1a421598cb83901c6d739e.Components.Pages.Apply
@using sv_ec1c5742dd1a421598cb83901c6d739e.Models

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]" Index="index" ShowRemove="References.Count > 2"
            OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires at least a name, relationship, and email.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

