@page "/apply"
@namespace sv_ec1c5742dd1a421598cb83901c6d739e.Components.Pages.Apply
@using sv_ec1c5742dd1a421598cb83901c6d739e.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo" ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="references" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter" CoverLetterChanged="UpdateCoverLetter"
                OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo" WorkEntries="workEntries" References="references"
                CoverLetter="@coverLetter" OnEdit="GoToStep" OnBack="PreviousStep"
                SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = string.Empty;

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void GoToStep(int step) => currentStep = step;
    private void UpdateCoverLetter(string value) => coverLetter = value;

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
                e.IsCurrentPosition ? null : e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

